#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-17

# Test: every entry inside a component directory must be a valid component. (#3482)
#
# Claude Code's plugin loader treats what it finds under `agents/` and `skills/`
# as components. It does not look for an opt-out. So a shared fragment parked
# inside those trees is not "co-located", it is LOADED:
#
#   plugins/ork/agents/shared/status-protocol.md  had no frontmatter at all, and
#   still appeared in a live session's agent roster as
#       ork:shared:status-protocol — Agent from ork plugin (Tools: All tools)
#   "All tools" because it declares nothing, which makes an include fragment the
#   single broadest tool surface in the roster.
#
#   plugins/ork/skills/shared/  was a directory in the skills tree with no
#   SKILL.md, i.e. not a skill.
#
# A consumer running /plugin sees "1 error during load" with no detail, because
# CC does not write plugin load errors to disk. So this class is invisible from
# the outside and has to be caught here.
#
# The fix is relocation, not frontmatter: shared material belongs in
# `shared/`, which build-plugins.sh already copies to plugins/ork/shared/.
#
# No here-strings below. Bash 5.3 pipes them back and deadlocks past PIPE_BUF
# (ork#3348, ork#3190), and a directory listing has no bounded size.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"

FAILED=0
echo "=== Component Directory Purity Test (#3482) ==="
echo ""

# --- agents: no subdirectories, and every *.md must carry frontmatter, because
#     CC loads whatever it finds either way.
for tree in src plugins/ork; do
    AGENTS="$REPO_ROOT/$tree/agents"
    # A missing tree is a failure, not a skip: with both trees absent this
    # printed zero check lines and RESULT: PASS (gate-fault-arm audit 2026-09-06).
    if [ ! -d "$AGENTS" ]; then
        echo "  FAIL: $tree/agents is missing; purity cannot be checked"
        FAILED=1
        continue
    fi
    echo "--- $tree/agents ---"

    subcount=0
    while IFS= read -r d; do
        echo "  FAIL: $(basename "$d")/ is a directory inside agents/; CC loads its .md files as agents"
        subcount=$((subcount + 1))
        FAILED=1
    done < <(find "$AGENTS" -mindepth 1 -maxdepth 1 -type d | sort)
    [ "$subcount" -eq 0 ] && echo "  PASS: no subdirectories"

    missing=0
    seen=0
    while IFS= read -r f; do
        seen=$((seen + 1))
        if [ "$(head -1 "$f")" != "---" ]; then
            echo "  FAIL: $(basename "$f") has no frontmatter, so it loads with no declared tools"
            missing=$((missing + 1))
            FAILED=1
        fi
    done < <(find "$AGENTS" -name '*.md' -type f | grep -viE '/(README|INDEX|CONTRIBUTING)\.md$' | sort)
    if [ "$seen" -eq 0 ]; then
        echo "  FAIL: $tree/agents holds zero agent .md files; nothing was checked"
        FAILED=1
    fi
    [ "$missing" -eq 0 ] && [ "$seen" -gt 0 ] && echo "  PASS: every agent .md carries frontmatter ($seen)"
    echo ""
done

# --- skills: every directory under skills/ must actually be a skill.
for tree in src plugins/ork; do
    SKILLS="$REPO_ROOT/$tree/skills"
    if [ ! -d "$SKILLS" ]; then
        echo "  FAIL: $tree/skills is missing; purity cannot be checked"
        FAILED=1
        continue
    fi
    echo "--- $tree/skills ---"
    bad=0
    seen=0
    while IFS= read -r d; do
        seen=$((seen + 1))
        if [ ! -f "$d/SKILL.md" ]; then
            echo "  FAIL: $(basename "$d")/ has no SKILL.md, so it is a directory in the skills tree that is not a skill"
            bad=$((bad + 1))
            FAILED=1
        fi
    done < <(find "$SKILLS" -mindepth 1 -maxdepth 1 -type d | sort)
    if [ "$seen" -eq 0 ]; then
        echo "  FAIL: $tree/skills holds zero skill directories; nothing was checked"
        FAILED=1
    fi
    [ "$bad" -eq 0 ] && [ "$seen" -gt 0 ] && echo "  PASS: every skills/ subdirectory has a SKILL.md ($seen)"
    echo ""
done

echo "=== Summary ==="
if [ "$FAILED" -ne 0 ]; then
    echo "RESULT: FAIL"
    echo ""
    echo "Move shared material to src/shared/ (build-plugins.sh already copies it"
    echo "to plugins/ork/shared/) and repoint the Read() references."
    exit 1
fi
echo "RESULT: PASS"
exit 0
